def repeatsToContain(a, b):
    m = len(b)
    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k and b[i] != b[k]:
            k = pi[k - 1]
        if b[i] == b[k]:
            k += 1
        pi[i] = k

    def contains(t):
        k = 0
        for c in t:
            while k and c != b[k]:
                k = pi[k - 1]
            if c == b[k]:
                k += 1
            if k == m:
                return True
        return False

    k0 = -(-m // len(a))
    if contains(a * k0):
        return k0
    if contains(a * (k0 + 1)):
        return k0 + 1
    return -1
